}", "parsed": {"doi": null, "year": 2026, "gs_id": null, "pm_id": null, "title": "Correlation of biochemical and imaging markers with hepatic adenoma in patients with glycogen storage disease: a retrospective single-center study", "authors": ["Ahn, Jhii-Hyun", "Cha, Seung Whan", "Kang, Yunkoo"], "journal": "Orphanet Journal of Rare Diseases", "abstract": "Patients with GSD type I have a lifetime hepatic adenoma risk of up to 70–80\%, whereas GSD type III carries a risk of approximately 20–40\%. Current European Study on Glycogen", "keywords": []}, "source": "Google Scholar", "metadata": {}, "paper_url": "https://link.springer.com/article/10.1186/s13023-026-04239-z", "full_abstract": "Background Hepatic adenoma is a serious complication of glycogen storage disease, particularly types I and III. However, noninvasive predictors of adenoma presence and progression for use in clinical practice remain limited. In this retrospective study, we included 93 patients with genetically confirmed glycogen storage disease who underwent liver ultrasonography, FibroScan, shear wave elastography, and routine biochemical testing between December 2020 and March 2025. Patients with and without hepatic adenoma were compared to identify discriminative variables, which were used to construct a logistic regression model. Patients with serial imaging data were assessed for changes in adenoma size and clinical parameters. Results Of the 93 patients included, 13 (14%) had hepatic adenomas. Age, gamma-glutamyl transferase levels, triglyceride levels, liver stiffness measured by FibroScan, and total cholesterol levels were significantly elevated in patients with adenoma compared to those without adenoma ( p 60 IU/L, triglycerides > 300 mg/dL, liver stiffness by FibroScan > 6.0, FibroScan Controlled Attenuation Parameter > 280 dB/m, and total cholesterol > 220 mg/dL were determined from group comparisons and the logistic regression model. Conclusions The findings suggest that routine biochemical markers, together with selected elastographic parameters for supportive assessment, can aid in the detection and risk stratification of hepatic adenomas in patients with glycogen storage disease. The use of data-derived clinical thresholds may help guide surveillance strategies and facilitate earlier identification of patients potentially at increased risk.", "abstract_snippet": "Patients with GSD type I have a lifetime hepatic adenoma risk of up to 70–80%, whereas GSD type III carries a risk of approximately 20–40%. Current European Study on Glycogen", "has_full_abstract": true, "main_abstract_source": "publisher_page", "gs_use_publisher_full_abstract": false, "title_refetch_main_abstract_source": "bibtex", "abstract_supplemented_by_title_query": true}}

