}", "parsed": {"doi": null, "year": null, "gs_id": null, "pm_id": null, "title": "GLYCOGEN STORAGE DISEASE", "authors": ["ROVIATI, EVI"], "journal": null, "abstract": "dari Carl Cori dan Gerty Cory yang memperoleh Nobel tahun 1947 karena menjelaskan penyakit ini, atau penyakit Forbe, yang menjelaskan penyakit ini lebih jauh atau limit dextrinosis", "keywords": []}, "source": "Google Scholar", "metadata": {}, "paper_url": "https://www.academia.edu/download/44630559/MAKALAH_GSD.pdf", "abstract_snippet": "dari Carl Cori dan Gerty Cory yang memperoleh Nobel tahun 1947 karena menjelaskan penyakit ini, atau penyakit Forbe, yang menjelaskan penyakit ini lebih jauh atau limit dextrinosis", "has_full_abstract": false, "main_abstract_source": "bibtex", "gs_use_publisher_full_abstract": false, "title_refetch_main_abstract_source": "snippet", "abstract_supplemented_by_title_query": true}}

